// ---------------------------------------------------------------- Mode Gakuen Cocoon Tower (203.65 m, 50 F, 2008)
// An elliptical shaft (fitted to the OSM footprint) that swells a little and tapers to a rounded top, dark glass wrapped in the white
// lattice of curved diagonal bands (two opposite families that close into long ovals).
LANDMARKS.tycocoon = {zh:'东京MODE学园蚕茧大厦', en:'Mode Gakuen Cocoon Tower', cat:'new', r:32, h:204,
  lt:{m:1, c:'#e3ecff', k:0.6},
  build(){
    const g = new THREE.Group(), B = mkB(), F = FD.tycocoon, gf = gL('tycocoon'), H = 203.65;
    const ax = axesP(F.ring), A0 = ax.sa*0.985, B0 = ax.sb*0.985, cx = ax.c[0], cz = ax.c[1], ux = ax.ux, uz = ax.uz;
    // plan scale along the height: full at the foot, swelling to 1.04 at 35 %, tapering to the rounded top
    const sc = t => t < 0.35 ? 1 + 0.04*Math.sin(t/0.35*HP) : t < 0.93 ? 1.04 - 0.36*Math.pow((t - 0.35)/0.58, 1.6) : 0.68*Math.sqrt(Math.max(0, 1 - Math.pow((t - 0.93)/0.07, 2)))*0.98 + 0.02;
    const NS = 56, pt = (th, t, off) => { const s = sc(t), a = A0*s + (off || 0), b = B0*s + (off || 0), lx = Math.cos(th)*a, lz = Math.sin(th)*b; return [cx + lx*ux - lz*uz, t*H, cz + lx*uz + lz*ux]; };
    const secs = []; for (let k = 0; k <= 48; k++){ const t = k/48, R = []; for (let i = 0; i < NS; i++) R.push(pt(i/NS*TAU, t, 0)); secs.push(R); }
    loftP(B.p({c:'#56697e', m:1, fh:4.0, cw:2.6}), secs, true);
    // plinth / ground-floor ring
    { const R = []; for (let i = 0; i < NS; i++){ const p = pt(i/NS*TAU, 0, 0.3); R.push([p[0], p[2]]); } plinthP(B.p('#cfd2d4'), R, gf, 0.3); }
    // lattice: two families of curved bands, 9 each, half a turn over the height, wavy so they close into ovals
    const LAT = B.p({c:'#f2f3f1', m:0, lc:'#f4f8ff', lk:0.9}), NB = 9, NSTEP = 90;
    for (const dir of [1, -1]) for (let k = 0; k < NB; k++){
      const th0 = k/NB*TAU; let prev = null;
      for (let s = 0; s <= NSTEP; s++){
        const t = s/NSTEP; if (t > 0.985) break;
        const th = th0 + dir*(t*PI*1.0 + 0.22*Math.sin(t*TAU*1.5)), p = pt(th, t, 0.55), q = pt(th + 0.035*dir, t + 0.004, 0.55);
        const w = 0.75 + 0.5*Math.sin(t*PI);  // band half-width (m), widest at mid-height
        const nx = p[0] - cx, nz = p[2] - cz, nl = Math.hypot(nx, nz) || 1, tx = -nz/nl, tz = nx/nl;
        const L = [p[0] - tx*w, p[1], p[2] - tz*w], R = [p[0] + tx*w, p[1], p[2] + tz*w];
        if (prev) quadP(LAT, prev[0], prev[1], R, L);
        prev = [L, R];
      }
    }
    // horizontal white rings at the foot and near the top
    for (const t of [0.012, 0.93]){ for (let i = 0; i < NS; i++){ const a = pt(i/NS*TAU, t, 0.6), b = pt((i+1)/NS*TAU, t, 0.6); quadP(LAT, a, b, [b[0], b[1] + 1.2, b[2]], [a[0], a[1] + 1.2, a[2]]); } }
    avLight(B, cx, H - 0.2, cz, 0.9);
    B.flush(g); return g; }};

// ---------------------------------------------------------------- Shinjuku Park Tower (235 m, 52 F, 1994)
