    const IN = (() => { const c = cenP(P); return P.map(p => [c[0] + (p[0]-c[0])*0.4, c[1] + (p[1]-c[1])*0.4]); })();
    { const o = B.p('#9da1a3'); const ring = []; fieldRoof(o, P, [IN.slice().reverse()], () => H, 4); }
    flatP(B.p({c:'#8aa0b0', glow:'#dfe9ff', gk:0.25}), IN, H - 1.2); prismP(B.p('#9da1a3'), IN, H - 1.2, H, true, true);
