    for (const f of by('forest')) scatter(ctx, f.r, 8.5, okB, () => { const r = ctx.rng(); return r < 0.66 ? 'd' : r < 0.72 ? 'ginkgo' : r < 0.9 ? 'plane' : 'pine'; }, () => 3.2 + ctx.rng()*1.2);
    // the cherry tree area
    for (const f of by('sakura')) scatter(ctx, f.r, 7, okB, () => 'sakura', () => 3 + ctx.rng()*0.9);
